public class DownscaleChangeSprite : MonoBehaviour
{
	public Sprite normal;

	public Sprite downscaled;

	private Image img;

	private void Start()
	{
		CheckScale();
	}

	private void OnEnable()
	{
		CheckScale();
	}

	public void CheckScale()
	{
		if (img == null)
		{
			img = GetComponent<Image>();
		}
