import os,re,collections
root=r"C:\Users\JJ\Documents\Proyecto predeterminado\ultrakill-webport\export\ExportedProject\Assets\Scenes"
names=['Pixelization','Texture Warping','Vertex Warping','Color Compression']
for fn in sorted(os.listdir(root)):
    if not fn.endswith('.unity'): continue
    p=os.path.join(root,fn)
    b=open(p,'rb').read(); t=b.decode('utf-8',errors='replace')
    if '--PSX SETTINGS--' not in t: continue
    lines=t.splitlines()
    blocks={}; order=[]
    for i,l in enumerate(lines):
        m=re.match(r'--- !u!(\d+) &(\d+)',l)
        if m: blocks[m.group(2)]=(m.group(1),i); order.append((i,m.group(2),m.group(1)))
    def body(fid):
        typ,i=blocks[fid]; out=[]
        for j in range(i,min(i+400,len(lines))):
            if lines[j].startswith('---') and j>i: break
            out.append(lines[j])
        return out
    def field(fid,key):
        for l in body(fid):
            s=l.strip()
            if s.startswith(key+':'): return s.split(':',1)[1].strip()
    def fid(s):
        m=re.search(r'fileID: (\d+)',s or ''); return m.group(1) if m else None
    found=collections.Counter(); headers=[]
    for i,fidv,typ in order:
        if typ!='1': continue
        nm=field(fidv,'m_Name')
        if nm in names:
            found[nm]+=1
    for i,fidv,typ in order:
        if typ!='114': continue
        txt=field(fidv,'m_Text')
        if txt and '--PSX SETTINGS--' in txt:
            go=fid(field(fidv,'m_GameObject'))
            headers.append((go,field(go,'m_Name'),repr(txt)))
    print(fn, dict(found), 'headers', headers)

