import os, re, sys

ROOT = r"C:\Users\JJ\Documents\Proyecto predeterminado\ultrakill-webport\export\ExportedProject\Assets\Scenes"
TARGET_NAMES = {"Pixelization", "Texture Warping", "Vertex Warping", "Color Compression"}
APPLY = "--apply" in sys.argv

def field(lines, start, end, key):
    for j in range(start, end):
        s = lines[j].strip()
        if s.startswith(key + ":"):
            return s.split(":", 1)[1].strip()
    return None

def ref_id(s):
    m = re.search(r"fileID:\s*(\d+)", s or "")
    return m.group(1) if m else None

total_files = 0
total_changes = 0
for fn in sorted(os.listdir(ROOT)):
    if not fn.endswith(".unity"):
        continue
    p = os.path.join(ROOT, fn)
    raw = open(p, "rb").read()
    text = raw.decode("utf-8", errors="replace")
    if "--PSX SETTINGS--" not in text:
        continue
    lines = raw.splitlines(keepends=True)
    # block map: fid -> (type, start, end)
    blocks = {}
    order = []
    for i, lb in enumerate(lines):
        l = lb.decode("utf-8", errors="replace").rstrip("\r\n")
        m = re.match(r"--- !u!(\d+) &(\d+)", l)
        if m:
            if order:
                blocks[order[-1][1]] = (order[-1][0], order[-1][2], i)
            order.append((m.group(1), m.group(2), i))
    if order:
        blocks[order[-1][1]] = (order[-1][0], order[-1][2], len(lines))

    go_targets = set()
    header_go = None
    # find header text GO
    for fid, (typ, s, e) in blocks.items():
        if typ != "114":
            continue
        txt = field(lines, s, e, "m_Text")
        if txt and "--PSX SETTINGS--" in txt:
            header_go = ref_id(field(lines, s, e, "m_GameObject"))
    # find named GO targets
    for fid, (typ, s, e) in blocks.items():
        if typ != "1":
            continue
        nm = field(lines, s, e, "m_Name")
        if nm in TARGET_NAMES:
            go_targets.add(fid)
    if header_go:
        go_targets.add(header_go)

    target_names = []
    for fid in sorted(go_targets):
        if fid not in blocks:
            continue
        typ, s, e = blocks[fid]
        target_names.append(field(lines, s, e, "m_Name"))

    changes = 0
    details = []
    if APPLY:
        for fid in go_targets:
            if fid not in blocks:
                continue
            typ, s, e = blocks[fid]
            for j in range(s, e):
                l = lines[j].decode("utf-8", errors="replace")
                m = re.match(r"^(\s*m_IsActive:\s*)([01])(\s*)$", l.rstrip("\r\n"))
                if m:
                    if m.group(2) == "1":
                        eol = l[len(l.rstrip("\r\n")):]
                        new = m.group(1) + "0" + eol
                        lines[j] = new.encode("utf-8")
                        changes += 1
                    details.append((field(lines, s, e, "m_Name"), m.group(2)))
                    break

    print(fn, "targets:", len(go_targets), sorted(target_names), "changes:", changes if APPLY else "-")
    if APPLY:
        if len(go_targets) != 5 or changes != 5:
            print("  !! UNEXPECTED COUNT, NOT WRITING")
            continue
        open(p, "wb").write(b"".join(lines))
        total_files += 1
        total_changes += changes

if APPLY:
    print("FILES WRITTEN", total_files, "TOTAL CHANGES", total_changes)

