import os,re
root=r"C:\Users\JJ\Documents\Proyecto predeterminado\ultrakill-webport\export\ExportedProject\Assets\Scenes"
names=['Pixelization','Texture Warping','Vertex Warping','Color Compression']
issues=[]; files=0
for fn in sorted(os.listdir(root)):
    if not fn.endswith('.unity'): continue
    p=os.path.join(root,fn); t=open(p,'rb').read().decode('utf-8',errors='replace')
    if '--PSX SETTINGS--' not in t: continue
    files+=1
    lines=t.splitlines(); blocks={}
    for i,l in enumerate(lines):
        m=re.match(r'--- !u!(\d+) &(\d+)',l)
        if m: blocks[m.group(2)]=(m.group(1),i)
    def body(fid):
        typ,i=blocks[fid]; out=[]
        for j in range(i,min(i+400,len(lines))):
            if lines[j].startswith('---') and j>i: break
            out.append(lines[j])
        return out
    def field(fid,key):
        for l in body(fid):
            s=l.strip()
            if s.startswith(key+':'): return s.split(':',1)[1].strip()
    def fid(s):
        m=re.search(r'fileID: (\d+)',s or ''); return m.group(1) if m else None
    act={}
    for f,(typ,i) in blocks.items():
        if typ=='1':
            nm=field(f,'m_Name')
            if nm in names or nm=='Text (5)': act[nm]=field(f,'m_IsActive')
    for f,(typ,i) in blocks.items():
        if typ=='114':
            txt=field(f,'m_Text')
            if txt and '--PSX SETTINGS--' in txt:
                go=fid(field(f,'m_GameObject')); act['HEADER']=field(go,'m_IsActive')
    vals=set(act.values()); 
    if vals!={'0'} or len(act)!=5: issues.append((fn,act))
print('scenes with PSX section:',files)
print('issues:',issues if issues else 'none')
